        purpose=[
            'A profile tells the story behind the product: the founder, the rider, the customer whose life it changed. Shot documentary-style with interviews and real environments, it’s the content people watch to the end, and the source of a season of shorter pieces. Route’s profile features, 686’s rider and designer stories, and Solidroad’s founder and customer interviews all started this way.',
            'We produce the full arc: pre-interviews and story outlines, a small crew that puts subjects at ease, and an edit that finds the narrative. Then we cut it down, trailers, vertical clips and quotes, so one profile fills a month of social.',
        ],
        facts=[('Best for', 'Founder and team stories, customer features, rider and athlete profiles, and YouTube series.'),
               ('Deliverables', 'A long-form film or episode, a trailer, vertical clips, and pull-quote stills.'),
               ('How it’s scoped', 'A production, scoped per project or per series. Cutdowns and clips run on the Monthly Partnership.'),
               ('Turnaround', 'Set per project; clips and the trailer within a week of the main cut on average.')],
        benefits=[('talent', 'Trust at length', 'A real person telling a real story does what no ad can: it earns the kind of trust that turns viewers into customers.'),
                  ('layers', 'One story, many pieces', 'The film, a trailer, vertical clips and quote stills all come from the same day, cut for YouTube, social and paid.'),
                  ('repeat', 'A series that compounds', 'A repeatable format, a recurring crew and a release cadence turn one profile into a channel.')],
        steps=[('Story & subjects', 'Who the profile is about, what it has to say, and where it will run.'),
               ('Pre-interviews & outline', 'Our director talks with each subject first, so the arc is clear before the camera rolls.'),
               ('Shoot', 'Interviews and b-roll with a small crew, in the places the story actually happens.'),
               ('Edit & finish', 'The narrative cut, color, sound and titles, reviewed in the app.'),
               ('Series & cutdowns', 'The trailer, vertical clips and stills, and the next episode planned from the first.')],
        formats=['Founder & profile videos', 'Docu-series episodes', 'Customer stories', 'Athlete & rider features', 'Long-form YouTube', 'Trailers', 'Vertical clips', 'Interview stills'],
        hero=[NOV8['whoop-behind-the-drivers-seat-lewis'], '2024/06/Route-22In-The-Studio22-with-Elwood.jpg', '2024/06/Culture-Shifters-Morgan-Collett.jpg'],
